import React from 'react';
import { BasePanel, Panel, QuotePanelConfig } from '@/types/StoryConfig';
import { TextPanel } from './TextPanel/TextPanel';
import { ImagePanel } from './ImagePanel/ImagePanel';
import { MapPanel } from './map/MapPanel';
import { VideoPanel } from './VideoPanel/VideoPanel';
import { ManualPoiMapPanel } from './map/ManualPoiMapPanel';
import { AutoPoiMapPanel } from './map/AutoPoiMapPanel';
import { QuotePanel } from './QuotePanel/QuotePanel';
import { SlideshowPanel } from './SlideshowPanel/SlideshowPanel';
import { DoormatPanel } from './DoormatPanel/DoormatPanel';
import { Box, Typography } from '@mui/material';
import { getSxClasses } from './PanelRenderer-style';

interface PanelRendererProps {
  panel: Panel;
  panelInstanceId?: string;
}

export const PanelRenderer: React.FC<PanelRendererProps> = ({ panel, panelInstanceId }) => {
  const classes = getSxClasses();

  switch (panel.type) {
    case 'text':
      return <TextPanel panel={panel} />;
    case 'image':
      return <ImagePanel panel={panel} />;
    case 'map':
      return <MapPanel panel={panel} panelInstanceId={panelInstanceId} />;
    case 'manual-poi-map':
      return <ManualPoiMapPanel panel={panel} panelInstanceId={panelInstanceId} />;
    case 'auto-poi-map':
      return <AutoPoiMapPanel panel={panel} panelInstanceId={panelInstanceId} />;
    case 'video':
      return <VideoPanel panel={panel} />;
    case 'quote':
      return <QuotePanel {...(panel as QuotePanelConfig)} />;
    case 'slideshow':
      return <SlideshowPanel panel={panel} />;
    case 'doormat':
      return <DoormatPanel panel={panel} />;
    default:
      return (
        <Box sx={classes.errorPlaceholder}>
          <Typography>Unknown panel type: {(panel as BasePanel).type}</Typography>
        </Box>
      );
  }
};
