import { useEffect, useRef, RefObject } from 'react';
import { getActiveSlideIndex, setActiveSlideIndex, useActiveSlideIndex } from '@/core/stores/StoryStore';

/**
 * Hook to track which slide is currently in the viewport
 * and update URL hash accordingly. Active index lives in StoryStore (not local
 * state) so it has one source of truth and comparisons never use a stale value.
 */
export const useScrollSpy = (
  slideRefs: RefObject<HTMLElement | null>[],
  slideIds: string[],
  enabled: boolean = true
): number => {
  const activeIndex = useActiveSlideIndex();
  const observerRef = useRef<IntersectionObserver | null>(null);
  const intersectionMapRef = useRef<Map<string, number>>(new Map());
  const commitTimeoutRef = useRef<number | null>(null);

  useEffect(() => {    
    if (!enabled || slideRefs.length === 0) {
      return;
    }

    // Clean up previous observer
    if (observerRef.current) {
      observerRef.current.disconnect();
    }

    // Reset intersection map
    intersectionMapRef.current = new Map();

    if (slideRefs.every(ref => ref.current === null)) {
      return;
    }

    // Create new IntersectionObserver
    observerRef.current = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.target.id) {
            // Store intersection ratio for each slide
            if (entry.isIntersecting) {
              intersectionMapRef.current.set(entry.target.id, entry.intersectionRatio);
            } else {
              intersectionMapRef.current.delete(entry.target.id);
            }
          }
        });

        // Find the slide with highest intersection ratio
        let maxRatio = 0;
        let maxId = '';
        intersectionMapRef.current.forEach((ratio, id) => {
          if (ratio > maxRatio) {
            maxRatio = ratio;
            maxId = id;
          }
        });

        // Debounced, not immediate: a slide suddenly growing/shrinking (e.g. an auto-POI map's
        // card list finishing an async load) fires this observer with a one-frame-transient ratio
        // distortion for every slide, which would otherwise get committed as a real navigation
        // before the layout (and any compensating scroll) actually settles. Only the last result
        // after things go quiet for a bit gets applied.
        if (maxId) {
          if (commitTimeoutRef.current) {
            window.clearTimeout(commitTimeoutRef.current);
          }
          commitTimeoutRef.current = window.setTimeout(() => {
            const index = slideIds.indexOf(maxId);
            if (index !== -1 && index !== getActiveSlideIndex()) {
              setActiveSlideIndex(index);

              // Update URL hash without scrolling
              const newHash = `#${maxId}`;
              if (window.location.hash !== newHash) {
                window.history.replaceState(null, '', newHash);
              }
            }
          }, 200);
        }
      },
      {
        root: null,
        rootMargin: '-20% 0px -20% 0px', // Trigger when 20% visible from top/bottom
        threshold: [0, 0.25, 0.5, 0.75, 1.0], // Multiple thresholds for better tracking
      }
    );

    // Observe all slide elements
    slideRefs.forEach((ref) => {
      if (ref.current) {
        observerRef.current?.observe(ref.current);
      }
    });

    return () => {
      observerRef.current?.disconnect();
      if (commitTimeoutRef.current) {
        window.clearTimeout(commitTimeoutRef.current);
      }
    };
  }, [slideRefs, slideIds, enabled]);

  return activeIndex;
};
